design_tokens.s:
Establish the design system and strip scaffold demo cruft. Everything later imports these tokens, so this is first.

DELETE (scaffold demos, all noise):
`src/routes/demo/`, `src/lib/vitest-examples/`, `e2e/` (if present), `src/routes/layout.css`.

CREATE `src/app.css` — the single stylesheet and the single source of design truth:
```css
@import 'tailwindcss';
@custom-variant dark (&:is(.dark *));

@theme {
	--font-sans: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
	--font-mono: ui-monospace, 'SF Mono', Menlo, monospace;

	--color-bg: oklch(0.16 0.008 260);
	--color-surface: oklch(0.21 0.01 260);
	--color-line: oklch(0.30 0.012 260);
	--color-ink: oklch(0.96 0.004 260);
	--color-muted: oklch(0.68 0.012 260);
	--color-accent: oklch(0.72 0.16 155);
	--color-danger: oklch(0.66 0.19 22);

	--radius-card: 0.75rem;
	--radius-field: 0.5rem;
}

@layer base {
	html {
		background: var(--color-bg);
		color: var(--color-ink);
		font-family: var(--font-sans);
	}
}
```
Dark-first on purpose: this is a utility people run at night over long videos, and one palette is half the CSS of two. Every later step uses `bg-surface text-ink border-line text-muted bg-accent text-danger rounded-card rounded-field` — NEVER a raw hex, rgb, or px value.

REWRITE `src/routes/+layout.svelte` to import `../app.css` instead of `./layout.css` (keep the favicon import and `{@render children()}` exactly as they are).

CREATE `src/lib/actions.ts` — required by ~/AGENTS.md for every user-input form (forms submit on Ctrl/Cmd+Enter ONLY; plain Enter stays browser-default):
```ts
export function ctrl_enter(node: HTMLElement, fn: () => void) {
	function on_key(e: KeyboardEvent) {
		if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
			e.preventDefault();
			fn();
		}
	}
	node.addEventListener('keydown', on_key);
	return { destroy: () => node.removeEventListener('keydown', on_key) };
}
```
Named `ctrl_enter` (snake_case house rule) even though ~/AGENTS.md writes it `ctrlEnter` — snake_case wins, it is the explicit naming rule.

CREATE `DESIGN.md`: one short page listing the tokens above, the dark-first decision, and the rule 'no raw css values, tokens only'.

WRITE `src/routes/+page.svelte` as a placeholder: an `<h1 class="text-ink">tldr</h1>` only. The real home UI arrives in `home_ui`.

TESTS — write these files EXACTLY as given, before any implementation. They are this step's contract: do not add, rename, reorder or weaken an assertion, and do not edit them later to make something pass.

`src/lib/__tests__/actions.test.ts`:
```ts
import { describe, it, expect, vi } from 'vitest';
import { ctrl_enter } from '$lib/actions';

function fake_node() {
	const h: Record<string, ((e: unknown) => void)[]> = {};
	return {
		addEventListener: (k: string, f: (e: unknown) => void) => {
			(h[k] ??= []).push(f);
		},
		removeEventListener: (k: string, f: (e: unknown) => void) => {
			h[k] = (h[k] ?? []).filter((x) => x !== f);
		},
		fire: (e: Record<string, unknown>) => (h.keydown ?? []).slice().forEach((f) => f(e))
	};
}

const ev = (o: Record<string, unknown>) => ({ key: 'Enter', ctrlKey: false, metaKey: false, preventDefault: () => {}, ...o });

describe('ctrl_enter', () => {
	it('fires on ctrl+enter', () => {
		const n = fake_node();
		const fn = vi.fn();
		ctrl_enter(n as unknown as HTMLElement, fn);
		n.fire(ev({ ctrlKey: true }));
		expect(fn).toHaveBeenCalledTimes(1);
	});

	it('fires on meta+enter', () => {
		const n = fake_node();
		const fn = vi.fn();
		ctrl_enter(n as unknown as HTMLElement, fn);
		n.fire(ev({ metaKey: true }));
		expect(fn).toHaveBeenCalledTimes(1);
	});

	it('does nothing on plain enter', () => {
		const n = fake_node();
		const fn = vi.fn();
		ctrl_enter(n as unknown as HTMLElement, fn);
		n.fire(ev({}));
		expect(fn).not.toHaveBeenCalled();
	});

	it('unbinds on destroy', () => {
		const n = fake_node();
		const fn = vi.fn();
		const { destroy } = ctrl_enter(n as unknown as HTMLElement, fn);
		destroy();
		n.fire(ev({ ctrlKey: true }));
		expect(fn).not.toHaveBeenCalled();
	});
});
```

