d1_schema.s:
Create the D1 database, the full schema, the query layer, and — most importantly — a real SQLite test harness so every later step can assert against actual SQL instead of a mock.

WRANGLER — add to `wrangler.jsonc` (keep the existing keys):
```jsonc
"d1_databases": [{ "binding": "DB", "database_name": "tldr", "database_id": "PLACEHOLDER", "migrations_dir": "migrations" }],
"r2_buckets": [{ "binding": "R2", "bucket_name": "tldr" }]
```
Leave `database_id` as the literal string PLACEHOLDER — the `deploy` step runs `wrangler d1 create tldr` and pastes the real id. Nothing before `deploy` touches remote D1.

CREATE `migrations/0001_init.sql`:
```sql
create table u (
  id text primary key,
  e text unique,
  p text,
  g text unique,
  n text,
  pic text,
  dv integer not null default 1,
  bal integer not null default 0,
  lg integer not null default 0,
  cr integer not null
);
create table pv (
  id text primary key,
  uid text not null,
  n text not null,
  b text not null,
  k text not null,
  m text,
  cr integer not null
);
create index pv_uid on pv (uid);
create table s (
  rid integer primary key autoincrement,
  id text unique not null,
  uid text not null,
  h text,
  t text not null,
  src text,
  ty text not null,
  md text not null,
  ln text not null,
  b text not null,
  tr text,
  pub integer not null default 0,
  cr integer not null
);
create index s_uid_cr on s (uid, cr desc);
create index s_h on s (h);
create table ce (
  id text primary key,
  uid text not null,
  k text not null,
  amt integer not null,
  bal integer not null,
  ref text unique,
  cr integer not null
);
create index ce_uid on ce (uid, cr desc);
create virtual table s_fts using fts5(t, b, content='s', content_rowid='rid');
create trigger s_ai after insert on s begin
  insert into s_fts(rowid, t, b) values (new.rid, new.t, new.b);
end;
create trigger s_ad after delete on s begin
  insert into s_fts(s_fts, rowid, t, b) values ('delete', old.rid, old.t, old.b);
end;
create trigger s_au after update on s begin
  insert into s_fts(s_fts, rowid, t, b) values ('delete', old.rid, old.t, old.b);
  insert into s_fts(rowid, t, b) values (new.rid, new.t, new.b);
end;
```
COLUMN MEANINGS (single-letter house rule): u = users; `dv` 1 while the account is device-only (never logged in), `bal` credit balance in kobo, `lg` epoch-ms of last daily grant, `cr` created-at ms. pv = providers; `n` label, `b` base url, `k` encrypted api key, `m` default model. s = summaries; `id` is the public ulid-ish id while `rid` exists ONLY because fts5 external-content tables require an INTEGER rowid — do not remove it, and never expose `rid` in a URL or JSON. `h` cache hash (null = not cacheable), `ty` one of `v|a|w|x` (video/audio/webpage/text), `ln` one of `s|m|l`, `b` summary markdown, `tr` R2 key of the transcript, `pub` 1 when publicly shared. ce = credit events; `k` one of `grant|purchase|deduct|refund`, `amt` signed kobo, `ref` the Paystack reference (UNIQUE — that unique index IS the double-credit guard, no separate lookup table needed).

CREATE `src/lib/server/db.ts` — thin, no ORM:
```ts
export type Db = D1Database;
export const now = () => Date.now();
export function new_id(): string {
	return crypto.randomUUID().replace(/-/g, '').slice(0, 24);
}
export async function one<T>(db: Db, sql: string, ...a: unknown[]): Promise<T | null> {
	return (await db.prepare(sql).bind(...a).first<T>()) ?? null;
}
export async function many<T>(db: Db, sql: string, ...a: unknown[]): Promise<T[]> {
	return (await db.prepare(sql).bind(...a).all<T>()).results ?? [];
}
export async function run(db: Db, sql: string, ...a: unknown[]): Promise<number> {
	const r = await db.prepare(sql).bind(...a).run();
	return r.meta.changes ?? 0;
}
```
`run` returning `meta.changes` is load-bearing — the credits step relies on it to detect whether a conditional UPDATE actually fired.

CREATE `src/lib/server/__tests__/mem_db.ts` — a ~45-line D1 shim over Node's built-in `node:sqlite` (Node 22, already the local runtime; its bundled SQLite has FTS5 compiled in — verified). Real SQL, real triggers, real fts5, zero dependencies:
```ts
import { DatabaseSync } from 'node:sqlite';
import { readFileSync } from 'node:fs';

export function mem_db(): D1Database {
	const db = new DatabaseSync(':memory:');
	db.exec(readFileSync('migrations/0001_init.sql', 'utf8'));
	const prep = (sql: string) => {
		let args: unknown[] = [];
		const api = {
			bind: (...a: unknown[]) => ((args = a), api),
			first: async <T>() => (db.prepare(sql).get(...(args as never[])) as T) ?? null,
			all: async <T>() => ({ results: db.prepare(sql).all(...(args as never[])) as T[] }),
			run: async () => {
				const r = db.prepare(sql).run(...(args as never[]));
				return { meta: { changes: Number(r.changes) } };
			}
		};
		return api;
	};
	return { prepare: prep } as unknown as D1Database;
}
```
`mem_db` also exposes `batch(stmts)`, wrapping the statements in a real `begin`/`commit`/`rollback` — `credits_d1` writes money through `db.batch([...])` and needs the rollback to be genuine, not simulated.

Every later server test builds its fixture with `mem_db()`. Do NOT reach for `@cloudflare/vitest-pool-workers` — it is a heavy dependency that buys nothing here.

TESTS — write these files EXACTLY as given, before any implementation. They are this step's contract: do not add, rename, reorder or weaken an assertion, and do not edit them later to make something pass.

`src/lib/server/__tests__/db.test.ts`:
```ts
import { describe, it, expect } from 'vitest';
import { mem_db } from './mem_db';
import { new_id, one, many, run } from '$lib/server/db';

const add_user = (db: D1Database, id: string) =>
	run(db, 'insert into u (id, n, dv, cr) values (?, ?, 1, ?)', id, 'n-' + id, Date.now());

const add_summary = (db: D1Database, id: string, uid: string, t: string, b: string) =>
	run(db, 'insert into s (id, uid, t, ty, md, ln, b, cr) values (?, ?, ?, ?, ?, ?, ?, ?)', id, uid, t, 'x', 'm', 'm', b, Date.now());

describe('db', () => {
	it('applies the migration cleanly', () => {
		expect(() => mem_db()).not.toThrow();
	});

	it('new_id returns 24 chars and never repeats', () => {
		expect(new_id()).toHaveLength(24);
		expect(new_id()).not.toBe(new_id());
	});

	it('round-trips a row through one()', async () => {
		const db = mem_db();
		await add_user(db, 'u1');
		const row = await one<{ id: string; dv: number }>(db, 'select id, dv from u where id = ?', 'u1');
		expect(row?.id).toBe('u1');
		expect(row?.dv).toBe(1);
	});

	it('run returns the number of rows it actually changed', async () => {
		const db = mem_db();
		await add_user(db, 'u1');
		expect(await run(db, 'update u set n = ? where id = ?', 'x', 'u1')).toBe(1);
		expect(await run(db, 'update u set n = ? where id = ?', 'x', 'nope')).toBe(0);
	});

	it('fts finds only the owner row (insert trigger + uid scoping)', async () => {
		const db = mem_db();
		await add_user(db, 'u1');
		await add_user(db, 'u2');
		await add_summary(db, 's1', 'u1', 'mine', 'hydrogen is the lightest element');
		await add_summary(db, 's2', 'u2', 'theirs', 'hydrogen appears here too');
		const rows = await many<{ id: string }>(
			db,
			"select s.id from s_fts join s on s.rid = s_fts.rowid where s_fts match ? and s.uid = ?",
			'hydrogen',
			'u1'
		);
		expect(rows.map((r) => r.id)).toEqual(['s1']);
	});

	it('fts follows an update (s_au trigger)', async () => {
		const db = mem_db();
		await add_user(db, 'u1');
		await add_summary(db, 's1', 'u1', 'mine', 'hydrogen');
		await run(db, 'update s set b = ? where id = ?', 'helium', 's1');
		const helium = await many(db, "select s.id from s_fts join s on s.rid = s_fts.rowid where s_fts match ?", 'helium');
		const hydrogen = await many(db, "select s.id from s_fts join s on s.rid = s_fts.rowid where s_fts match ?", 'hydrogen');
		expect(helium).toHaveLength(1);
		expect(hydrogen).toHaveLength(0);
	});
});
```

